  if(cmd==='n'||cmd==='N'){const all=e.lines.map((x,r)=>({r,i:x.indexOf(e.search)})).filter(x=>x.i>=0),direction=(cmd==='n'?1:-1)*(e.searchDirection||1);if(all.length){const found=direction===1?(all.find(x=>x.r>e.row)||all[0]):([...all].reverse().find(x=>x.r<e.row)||all.at(-1));e.row=found.r;e.col=found.i}renderEditor();evaluateEditor();return true}
  if((cmd===';'||cmd===',')&&e.lastFind){const reverse=cmd===',',dir=e.lastFind.direction,backward=dir==='F'||dir==='T',line=e.lines[e.row],findBackward=backward!==reverse,found=findBackward?line.lastIndexOf(e.lastFind.char,e.col-1):line.indexOf(e.lastFind.char,e.col+1);if(found>=0)e.col=found+(dir==='t'&&!reverse?-1:dir==='T'&&!reverse?1:0);clampCursor();renderEditor();evaluateEditor();return true}
  if((m=cmd.match(/^:(%?)s\/([^/]+)\/([^/]+)\/([gc]*)$/))){saveEditorUndo();const indexes=m[1]?e.lines.map((_,i)=>i):[e.row];for(const r of indexes){try{const re=new RegExp(m[2],m[4].includes('g')?'g':'');e.lines[r]=e.lines[r].replace(re,m[3])}catch{}}renderEditor();evaluateEditor();return true}
  if(cmd===':set number'||cmd===':set nu'||cmd===':set relativenumber'||cmd===':set rnu'){e.numberOn=true;e.relativeNumber=cmd.includes('relative')||cmd.endsWith('rnu');renderEditor();evaluateEditor();return true}if(cmd===':set nonumber'||cmd===':set nonu'){e.numberOn=false;renderEditor();return true}
  if(cmd===':w'||cmd===':wq'||cmd===':q'||cmd===':q!'){e.status=cmd;renderEditor();evaluateEditor();toast(cmd===':wq'?'Fichier enregistré':'Commande de fichier exécutée');return true}
  if(cmd===':bn'||cmd===':bnext'||cmd===`:e ${c.nextFile}`){if(c.nextLines){e.lines=[...c.nextLines];e.file=c.nextFile;e.status=cmd;renderEditor();evaluateEditor()}return true}
