  if((m=cmd.match(/^Ctrl-w\s+([hjkl])$/i))){e.windowDirection=m[1];e.status=`Ctrl-w ${m[1]}`;renderEditor();evaluateEditor();return true}
  if(cmd===':noh'){e.status=':noh';renderEditor();evaluateEditor();return true}
  if(cmd===':help'||cmd.startsWith(':help ')){e.status=':help';renderEditor();evaluateEditor();toast('Aide Vim : navigation, opérateurs, objets texte, registres');return true}
  if(cmd==='Ctrl-d'||cmd==='Ctrl-u'||cmd==='Ctrl-f'||cmd==='Ctrl-b'){e.row=Math.min(e.lines.length-1,Math.max(0,e.row+(cmd==='Ctrl-d'?6:cmd==='Ctrl-u'?-6:cmd==='Ctrl-f'?12:-12)));renderEditor();evaluateEditor();return true}
  if(cmd===':noh'){e.status=':noh';renderEditor();evaluateEditor();return true}
  if(cmd==='qa'){e.recording=true;e.recordedCommands=[];e.status='recording @a';renderEditor();toast('Enregistrement de la macro a');return true}
  if(cmd==='q'&&e.recording){e.recording=false;e.macros.a=[...e.recordedCommands];e.status='macro a enregistrée';renderEditor();toast('Macro enregistrée dans a');return true}
